const DISCLAIMER =
  "Research only — out-of-sample historical performance does not guarantee " +
  "future results. This report does not affect live or paper-trading strategy selection.";

// ── formatting: never render undefined/null/NaN/Infinity ───────────────────
function na(v: any, suffix = ""): string {
  if (v === null || v === undefined || v === "") return "N/A";
  if (typeof v === "number" && (!isFinite(v) || isNaN(v))) return "N/A";
  if (typeof v === "number") return `${+v.toFixed(2)}${suffix}`;
  if (typeof v === "boolean") return v ? "Yes" : "No";
  return String(v);
}

function reliabilityBadge(label?: string) {
  if (!label) return null;
  const cls: Record<string, string> = {
    "VERY LOW": "text-red-400 border-red-700",
    LOW: "text-amber-400 border-amber-700",
    LIMITED: "text-yellow-400 border-yellow-700",
    MODERATE: "text-sky-400 border-sky-700",
    STRONGER: "text-emerald-400 border-emerald-700",
  };
  return (
    <Badge variant="outline" className={cn("text-[9px] font-mono px-1", cls[label] ?? "text-zinc-400 border-zinc-600")}>
      {label}
    </Badge>
  );
}

// ── status badges (requirement 6): text + icon, never colour alone ─────────
export function StatusBadge({ value }: { value?: string }) {
  const s = String(value ?? "").toUpperCase().replace(/_/g, " ").trim();
  if (!s) return null;
  let icon = <Info className="h-3 w-3 mr-1" />;
  let cls = "text-zinc-300 border-zinc-600 bg-zinc-500/10";
  if (s === "PASS" || s.includes("PROMISING")) {
    icon = <CheckCircle2 className="h-3 w-3 mr-1" />; cls = "text-emerald-400 border-emerald-600 bg-emerald-500/10";
  } else if (s === "FAIL" || s.includes("REJECT")) {
    icon = <XCircle className="h-3 w-3 mr-1" />; cls = "text-red-400 border-red-600 bg-red-500/10";
  } else if (s.includes("WARNING") || s.includes("INCONCLUSIVE")) {
    icon = <AlertTriangle className="h-3 w-3 mr-1" />; cls = "text-amber-400 border-amber-600 bg-amber-500/10";
  } else if (s.includes("INSUFFICIENT")) {
    icon = <Info className="h-3 w-3 mr-1" />; cls = "text-zinc-300 border-zinc-600 bg-zinc-500/10";
  } else if (s.includes("CONTINUE")) {
    icon = <FlaskConical className="h-3 w-3 mr-1" />; cls = "text-sky-400 border-sky-600 bg-sky-500/10";
  } else if (s.includes("RESEARCH")) {
    icon = <ShieldAlert className="h-3 w-3 mr-1" />; cls = "text-violet-400 border-violet-600 bg-violet-500/10";
  }
  return (
    <Badge variant="outline" className={cn("font-mono text-[9px] px-1.5", cls)}>
      {icon}{s}
    </Badge>
  );
}

// ── scorecards (requirement 2) ──────────────────────────────────────────────
type CardState = "positive" | "negative" | "warning" | "neutral";
function stateFor(kind: string, v: any): CardState {
  if (v === null || v === undefined || (typeof v === "number" && (!isFinite(v) || isNaN(v)))) return "neutral";
  const n = Number(v);
  switch (kind) {
    case "return": case "pnl": case "expectancy": case "sharpe": return n > 0 ? "positive" : n < 0 ? "negative" : "neutral";
    case "pf": return n >= 1.3 ? "positive" : n >= 1 ? "warning" : "negative";
    case "dd": return n <= 10 ? "positive" : n <= 25 ? "warning" : "negative";
    case "wr": return n >= 50 ? "positive" : n >= 40 ? "warning" : "negative";
    case "score": return n >= 60 ? "positive" : n >= 35 ? "warning" : "negative";
    default: return "neutral";
  }
}
const CARD_CLS: Record<CardState, string> = {
  positive: "border-emerald-700/50 bg-emerald-500/5 text-emerald-300",
  negative: "border-red-700/50 bg-red-500/5 text-red-300",
  warning: "border-amber-700/50 bg-amber-500/5 text-amber-300",
  neutral: "border-zinc-700 bg-zinc-800/30 text-zinc-300",
};

function Scorecards({ es }: { es: any }) {
  const cards: [string, any, string, string][] = [
    ["Net Return", es.net_return_pct, "%", "return"],
    ["Net P&L", es.net_pnl, " ₹", "pnl"],
    ["Profit Factor", es.profit_factor, "", "pf"],
    ["Expectancy/Trade", es.expectancy_rs, " ₹", "expectancy"],
    ["Sharpe", es.sharpe, "", "sharpe"],
    ["Max Drawdown", es.max_drawdown_pct, "%", "dd"],
    ["Win Rate", es.win_rate, "%", "wr"],
    ["OOS Trades", es.oos_trades, "", "n"],
    ["Test Windows", es.windows, "", "n"],
    ["Evidence", es.evidence_verdict, "", "text"],
    ["Research Score", es.score, "/100", "score"],
  ];
  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-1.5">
      {cards.map(([label, v, suffix, kind]) => (
        <div key={label} className={cn("border rounded-md px-2 py-1.5 min-w-0", CARD_CLS[stateFor(kind, kind === "text" ? null : v)])}>
          <p className="text-[8px] font-mono text-zinc-500 uppercase truncate">{label}</p>
          <p className="text-[11px] font-mono font-bold truncate">{na(v, suffix)}</p>
        </div>
      ))}
    </div>
  );
}

// ── generic table (horizontally scrollable on screen, clean in print) ───────
function T({ rows, cols, suffixes = {}, limit = 30 }: {
  rows: any[]; cols: [string, string][]; suffixes?: Record<string, string>; limit?: number;
}) {
  if (!rows || !Array.isArray(rows) || rows.length === 0) {
    return <p className="text-[10px] font-mono text-zinc-500">Not available — no data recorded for this experiment.</p>;
  }
  return (
    <div className="overflow-x-auto report-table">
      <table className="w-full text-[10px] font-mono">
        <thead>
          <tr className="text-zinc-500 border-b border-zinc-800">
            {cols.map(([k, l]) => <th key={k} className="text-left py-1 pr-3 whitespace-nowrap">{l}</th>)}
          </tr>
        </thead>
        <tbody>
          {rows.slice(0, limit).map((r, i) => (
            <tr key={i} className="border-b border-zinc-800/50">
              {cols.map(([k]) => (
                <td key={k} className="py-1 pr-3 text-zinc-300 whitespace-nowrap">
                  {k === "sample_label" || k === "reliability" || k === "evidence"
                    ? (reliabilityBadge(r?.[k]) ?? na(r?.[k]))
                    : na(r?.[k], suffixes[k] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length > limit && <p className="text-[9px] font-mono text-zinc-600 mt-1">Showing {limit} of {rows.length} rows — full data in CSV export.</p>}
    </div>
  );
}

const BREAKDOWN_COLS: [string, string][] = [
  ["group", "Group"], ["trades", "Trades"], ["win_rate", "Win%"],
  ["net_pnl", "Net P&L"], ["expectancy_rs", "Exp ₹"], ["profit_factor", "PF"],
  ["avg_return_pct", "Avg Ret%"], ["sample_label", "Evidence"],
];

function KV({ obj, keys }: { obj: any; keys: [string, string, string?][] }) {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-x-4 gap-y-1 text-[10px] font-mono">
      {keys.map(([k, l, suffix]) => (
        <div key={k}><span className="text-zinc-500">{l} </span><span className="text-zinc-200">{na(obj?.[k], suffix ?? "")}</span></div>
      ))}
    </div>
  );
}

function Warnings({ list }: { list?: string[] }) {
  if (!list || list.length === 0) return null;
  return (
    <div className="space-y-1">
      {list.map((w, i) => (
        <div key={i} className="text-[10px] font-mono text-amber-400 bg-amber-500/10 border border-amber-500/30 rounded px-2 py-1 flex gap-1.5">
          <AlertTriangle className="h-3 w-3 flex-shrink-0 mt-0.5" />{w}
        </div>
      ))}
    </div>
  );
}

